SELECT (CASE WHEN (eixo_1.no_dependencia_admin = 'Privada') THEN eixo_1.mantenedora ELSE eixo_1.instituicao END) AS calculation_838513978982854656,   COUNT(DISTINCT eixo_1.calculation_838513981462429699) AS ctd:calculation_838513981462429699:ok,   eixo_1.municipio_do_local_da_oferta AS municipio_do_local_da_oferta,   eixo_1.nome_curso_catalogo_guia AS nome_curso_catalogo_guia,   eixo_1.uf_do_local_da_oferta AS uf_do_local_da_oferta,   CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) AS yr:data_de_inicio:ok FROM eixo_1 WHERE ((eixo_1.uf_do_local_da_oferta = 'PE') AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) IN ('CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'Não Matriculado', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL))) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY calculation_838513978982854656,   municipio_do_local_da_oferta,   nome_curso_catalogo_guia,   uf_do_local_da_oferta,   yr:data_de_inicio:ok;
